
--  FILE_NAME:         XHIBIT2_Standing_FormB_Result.sql                                                       
--  ENVIRONMENT:       Live, System, Pre-production          
--  DESCRIPTION:       This script populates xhb_formb_result  
--                     
--  STATUS DESCRIPTION:Script is suitable for running initially on set-up of the database on any environment.
--  DEPENDENCIES:      THIS SCRIPT SHOULD ONLY BE RUN ONCE ON INITIAL SET-UP OF THE DATABASE AFTER MERCATOR MAPS HAVE IMPORTED THE CREST REFERENCE                  
--  OWNER:             Nick Sawyer, Sandip Sangha
--

DELETE FROM XHB_FORMB_RESULT;

DECLARE 

  var_court_id NUMBER;

  CURSOR c_court_id IS
    SELECT court_id
    FROM   xhb_court;

BEGIN
  OPEN c_court_id;

  LOOP

    FETCH c_court_id
    INTO  var_court_id;

    EXIT WHEN c_court_id%NOTFOUND;



    COMMIT;

  END LOOP;

  CLOSE c_court_id;

END;
/
